use xiom.io;

use xiom.string;
fn cached_factorial(n: Int, cache: &mut Map[Int, Int]) -> Int {
  if cache.contains(&n) {
    return match cache.get(&n) { Some(v) => v, None => 0 };
  }
  if n <= 1 {
    cache.insert(n, 1);
    return 1;
  }
  let result = n * cached_factorial(n - 1, cache);
  cache.insert(n, result);
  return result;
}

fn main() -> Int {
  var cache: Map[Int, Int] = Map[Int, Int].new();
  let result = cached_factorial(6, &mut cache);
  io.println(string.int_to_str(result));
  io.println(string.int_to_str(cache.len()));
  return 0;
}
